import java.util.*;
class NarrowRiverWaterProfileTest{public static void main(String[]a){int n=128;float[] h=new float[n*n],spill=new float[n*n];int[] parent=new int[n*n];Arrays.fill(parent,-1);for(int z=0;z<n;z++)for(int x=0;x<n;x++){int i=z*n+x;h[i]=(float)(180-(x+z)*.6);spill[i]=h[i];if(x<n-1&&z<n-1)parent[i]=(z+1)*n+x+1;}var e=new EnvironmentMap(h.clone());e.water=new float[n*n];Arrays.fill(e.water,62);e.river=new float[n*n];e.material=new byte[n*n];NaturalRivers.trace(e,h,new EnvironmentNodes.Drainage(parent,spill),20*n+20,n,1024,62,.4375,2,Float.POSITIVE_INFINITY,1.5,71,1,.4,.5,true,()->false);double cut=0;for(var segment:e.ribbons.segments){var p=segment.a();cut=Math.max(cut,RiverShape.height(h,n,p.x()/8,p.z()/8)-p.water());}if(cut>4)throw new AssertionError("Dry preview cell collapsed vector water level: cut="+cut);System.out.println("PASS: narrow diagonal river retains water profile; maximum terrain above water="+cut);}}
